export const WIDTH = 360;
export const HEIGHT = 520;
export const FIXED_STEP = 1 / 120;
export const MAX_FRAME_TIME = 0.1;
export const START_LIVES = 3;
export const BRICK_POINTS = 10;
export const BALL_RADIUS = 6;

const PADDLE_WIDTH = 64;
const PADDLE_HEIGHT = 10;
const PADDLE_Y = HEIGHT - 38;
const PADDLE_SPEED = 300;
const BALL_SPEED = 280;
const BALL_MAX_SPEED = 460;
const BRICK_ROWS = 5;
const BRICK_COLS = 8;
const BRICK_WIDTH = 38;
const BRICK_HEIGHT = 16;
const BRICK_GAP_X = 6;
const BRICK_GAP_Y = 7;
const BRICK_TOP = 54;
const BRICK_COLORS = ['#f472b6', '#fb923c', '#facc15', '#4ade80', '#38bdf8'];
const MAX_SUBSTEPS = 64;
const EPSILON = 0.01;

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function createBricks() {
  const bricks = [];
  const gridWidth = BRICK_COLS * BRICK_WIDTH + (BRICK_COLS - 1) * BRICK_GAP_X;
  const offsetX = (WIDTH - gridWidth) / 2;
  for (let row = 0; row < BRICK_ROWS; row += 1) {
    for (let col = 0; col < BRICK_COLS; col += 1) {
      bricks.push({
        x: offsetX + col * (BRICK_WIDTH + BRICK_GAP_X),
        y: BRICK_TOP + row * (BRICK_HEIGHT + BRICK_GAP_Y),
        width: BRICK_WIDTH,
        height: BRICK_HEIGHT,
        row,
        col,
        color: BRICK_COLORS[row],
        points: BRICK_POINTS,
        alive: true
      });
    }
  }
  return bricks;
}

function attachBall(state) {
  const { ball, paddle } = state;
  ball.x = paddle.x + paddle.width / 2;
  ball.y = paddle.y - ball.radius - 2;
  ball.vx = 0;
  ball.vy = 0;
  ball.stuck = true;
}

export function createInitialState() {
  const state = {
    status: 'ready',
    score: 0,
    lives: START_LIVES,
    paddle: {
      x: (WIDTH - PADDLE_WIDTH) / 2,
      y: PADDLE_Y,
      width: PADDLE_WIDTH,
      height: PADDLE_HEIGHT,
      speed: PADDLE_SPEED
    },
    ball: {
      x: 0,
      y: 0,
      vx: 0,
      vy: 0,
      radius: BALL_RADIUS,
      stuck: true
    },
    bricks: createBricks(),
    input: { left: false, right: false }
  };
  attachBall(state);
  return state;
}

export function startGame(state) {
  if (state.status !== 'ready') return false;
  state.status = 'playing';
  return true;
}

export function restartGame(state) {
  const fresh = createInitialState();
  fresh.status = 'playing';
  for (const key of Object.keys(state)) delete state[key];
  Object.assign(state, fresh);
  return state;
}

export function pauseGame(state) {
  if (state.status !== 'playing') return false;
  state.status = 'paused';
  return true;
}

export function resumeGame(state) {
  if (state.status !== 'paused') return false;
  state.status = 'playing';
  return true;
}

export function togglePause(state) {
  if (state.status === 'playing') return pauseGame(state);
  if (state.status === 'paused') return resumeGame(state);
  return false;
}

export function launchBall(state) {
  if (state.status !== 'playing' || !state.ball.stuck) return false;
  state.ball.stuck = false;
  state.ball.vx = BALL_SPEED * 0.45;
  state.ball.vy = -Math.sqrt(BALL_SPEED * BALL_SPEED - state.ball.vx * state.ball.vx);
  return true;
}

export function setLeftPressed(state, pressed) {
  state.input.left = Boolean(pressed);
}

export function setRightPressed(state, pressed) {
  state.input.right = Boolean(pressed);
}

export function clearInput(state) {
  state.input.left = false;
  state.input.right = false;
}

function updatePaddle(state, dt) {
  const direction = Number(state.input.right) - Number(state.input.left);
  state.paddle.x = clamp(
    state.paddle.x + direction * state.paddle.speed * dt,
    0,
    WIDTH - state.paddle.width
  );
  if (state.ball.stuck) attachBall(state);
}

function circleHitsRect(ball, rect) {
  const closestX = clamp(ball.x, rect.x, rect.x + rect.width);
  const closestY = clamp(ball.y, rect.y, rect.y + rect.height);
  const dx = ball.x - closestX;
  const dy = ball.y - closestY;
  return dx * dx + dy * dy <= ball.radius * ball.radius;
}

function bounceOffBrick(ball, brick, prevX, prevY) {
  const r = ball.radius;
  const fromTop = ball.vy > 0 && prevY + r <= brick.y + EPSILON;
  const fromBottom = ball.vy < 0 && prevY - r >= brick.y + brick.height - EPSILON;
  const fromLeft = ball.vx > 0 && prevX + r <= brick.x + EPSILON;
  const fromRight = ball.vx < 0 && prevX - r >= brick.x + brick.width - EPSILON;

  if (fromTop || fromBottom) {
    if (fromTop) {
      ball.y = brick.y - r - EPSILON;
      ball.vy = -Math.abs(ball.vy);
    } else {
      ball.y = brick.y + brick.height + r + EPSILON;
      ball.vy = Math.abs(ball.vy);
    }
    return;
  }

  if (fromLeft || fromRight) {
    if (fromLeft) {
      ball.x = brick.x - r - EPSILON;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.width + r + EPSILON;
      ball.vx = Math.abs(ball.vx);
    }
    return;
  }

  const overlapX = Math.min(
    ball.x + r - brick.x,
    brick.x + brick.width - (ball.x - r)
  );
  const overlapY = Math.min(
    ball.y + r - brick.y,
    brick.y + brick.height - (ball.y - r)
  );

  if (overlapX < overlapY) {
    if (ball.vx > 0) {
      ball.x = brick.x - r - EPSILON;
      ball.vx = -Math.abs(ball.vx);
    } else {
      ball.x = brick.x + brick.width + r + EPSILON;
      ball.vx = Math.abs(ball.vx);
    }
  } else if (ball.vy > 0) {
    ball.y = brick.y - r - EPSILON;
    ball.vy = -Math.abs(ball.vy);
  } else {
    ball.y = brick.y + brick.height + r + EPSILON;
    ball.vy = Math.abs(ball.vy);
  }
}

function advanceBall(state, dt) {
  const events = [];
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  if (ball.x - ball.radius < 0) {
    ball.x = ball.radius;
    ball.vx = Math.abs(ball.vx);
    events.push('wall');
  } else if (ball.x + ball.radius > WIDTH) {
    ball.x = WIDTH - ball.radius;
    ball.vx = -Math.abs(ball.vx);
    events.push('wall');
  }

  if (ball.y - ball.radius < 0) {
    ball.y = ball.radius;
    ball.vy = Math.abs(ball.vy);
    events.push('wall');
  }

  const crossedPaddleTop = prevY + ball.radius <= paddle.y + EPSILON;
  const overlapsPaddleY =
    ball.y + ball.radius >= paddle.y && ball.y - ball.radius <= paddle.y + paddle.height;
  const overlapsPaddleX =
    ball.x + ball.radius >= paddle.x && ball.x - ball.radius <= paddle.x + paddle.width;

  if (ball.vy > 0 && crossedPaddleTop && overlapsPaddleY && overlapsPaddleX) {
    ball.y = paddle.y - ball.radius - EPSILON;
    const offset = clamp(
      (ball.x - (paddle.x + paddle.width / 2)) / (paddle.width / 2),
      -1,
      1
    );
    const angle = offset * (Math.PI / 3);
    const speed = clamp(
      Math.hypot(ball.vx, ball.vy) * 1.015,
      BALL_SPEED,
      BALL_MAX_SPEED
    );
    ball.vx = Math.sin(angle) * speed;
    ball.vy = -Math.cos(angle) * speed;
    events.push('paddle');
  }

  for (const brick of state.bricks) {
    if (!brick.alive || !circleHitsRect(ball, brick)) continue;
    brick.alive = false;
    state.score += brick.points;
    bounceOffBrick(ball, brick, prevX, prevY);
    events.push('brick');
    if (state.bricks.every((item) => !item.alive)) {
      state.status = 'won';
      events.push('won');
    }
    break;
  }

  if (ball.y - ball.radius > HEIGHT) {
    state.lives -= 1;
    if (state.lives <= 0) {
      state.lives = 0;
      state.status = 'gameover';
      events.push('gameover');
    } else {
      attachBall(state);
      events.push('lifeLost');
    }
  }

  return events;
}

export function step(state, dt) {
  if (state.status !== 'playing' || !Number.isFinite(dt) || dt <= 0) return [];

  const boundedDt = Math.min(dt, MAX_FRAME_TIME);
  updatePaddle(state, boundedDt);
  if (state.ball.stuck) return [];

  const speed = Math.hypot(state.ball.vx, state.ball.vy);
  const travel = speed * boundedDt;
  const substeps = Math.min(
    MAX_SUBSTEPS,
    Math.max(1, Math.ceil(travel / (state.ball.radius * 0.6)))
  );
  const slice = boundedDt / substeps;
  const events = [];

  for (let index = 0; index < substeps; index += 1) {
    events.push(...advanceBall(state, slice));
    if (state.status !== 'playing' || state.ball.stuck) break;
  }

  return events;
}

import { WIDTH, HEIGHT } from './game.js';

function roundedRect(ctx, x, y, width, height, radius) {
  const r = Math.min(radius, width / 2, height / 2);
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.lineTo(x + width - r, y);
  ctx.quadraticCurveTo(x + width, y, x + width, y + r);
  ctx.lineTo(x + width, y + height - r);
  ctx.quadraticCurveTo(x + width, y + height, x + width - r, y + height);
  ctx.lineTo(x + r, y + height);
  ctx.quadraticCurveTo(x, y + height, x, y + height - r);
  ctx.lineTo(x, y + r);
  ctx.quadraticCurveTo(x, y, x + r, y);
  ctx.closePath();
}

export function render(ctx, state) {
  ctx.setTransform(ctx.canvas.width / WIDTH, 0, 0, ctx.canvas.height / HEIGHT, 0, 0);
  ctx.clearRect(0, 0, WIDTH, HEIGHT);

  const background = ctx.createLinearGradient(0, 0, WIDTH, HEIGHT);
  background.addColorStop(0, '#081226');
  background.addColorStop(0.55, '#0b1730');
  background.addColorStop(1, '#050914');
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  ctx.strokeStyle = 'rgba(148, 163, 184, 0.06)';
  ctx.lineWidth = 1;
  for (let y = 24; y < HEIGHT; y += 32) {
    ctx.beginPath();
    ctx.moveTo(0, y + 0.5);
    ctx.lineTo(WIDTH, y + 0.5);
    ctx.stroke();
  }

  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.save();
    ctx.shadowColor = brick.color;
    ctx.shadowBlur = 10;
    ctx.fillStyle = brick.color;
    roundedRect(ctx, brick.x, brick.y, brick.width, brick.height, 4);
    ctx.fill();
    ctx.restore();
    ctx.fillStyle = 'rgba(255, 255, 255, 0.28)';
    roundedRect(ctx, brick.x + 2, brick.y + 2, brick.width - 4, 3, 1.5);
    ctx.fill();
  }

  const paddle = state.paddle;
  ctx.save();
  ctx.shadowColor = 'rgba(56, 189, 248, 0.9)';
  ctx.shadowBlur = 16;
  const paddleGradient = ctx.createLinearGradient(paddle.x, 0, paddle.x + paddle.width, 0);
  paddleGradient.addColorStop(0, '#0ea5e9');
  paddleGradient.addColorStop(0.5, '#7dd3fc');
  paddleGradient.addColorStop(1, '#0ea5e9');
  ctx.fillStyle = paddleGradient;
  roundedRect(ctx, paddle.x, paddle.y, paddle.width, paddle.height, 5);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = 'rgba(255, 255, 255, 0.55)';
  roundedRect(ctx, paddle.x + 4, paddle.y + 2, paddle.width - 8, 2, 1);
  ctx.fill();

  const ball = state.ball;
  if (state.status === 'playing' && ball.stuck) {
    ctx.strokeStyle = 'rgba(148, 163, 184, 0.35)';
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 6]);
    ctx.beginPath();
    ctx.moveTo(ball.x, ball.y - ball.radius);
    ctx.lineTo(ball.x, Math.max(4, ball.y - 70));
    ctx.stroke();
    ctx.setLineDash([]);
  }

  ctx.save();
  ctx.shadowColor = 'rgba(255, 255, 255, 0.9)';
  ctx.shadowBlur = 14;
  ctx.fillStyle = '#f8fafc';
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

import {
  FIXED_STEP,
  MAX_FRAME_TIME,
  clearInput,
  createInitialState,
  launchBall,
  pauseGame,
  restartGame,
  resumeGame,
  setLeftPressed,
  setRightPressed,
  step
} from './game.js';
import { render } from './render.js';

const canvas = document.querySelector('#game');
const ctx = canvas.getContext('2d');
const scoreEl = document.querySelector('#score');
const livesEl = document.querySelector('#lives');
const statusEl = document.querySelector('#status');
const hintEl = document.querySelector('#hint');
const pauseBtn = document.querySelector('#pause');
const resumeBtn = document.querySelector('#resume');
const restartBtn = document.querySelector('#restart');
const overlay = document.querySelector('#overlay');
const overlayKicker = document.querySelector('#overlay-kicker');
const overlayTitle = document.querySelector('#overlay-title');
const overlayText = document.querySelector('#overlay-text');
const overlayAction = document.querySelector('#overlay-action');

const state = createInitialState();
const keys = new Set();
const touch = { left: false, right: false };
const activePointers = { left: new Set(), right: new Set() };
const statusLabels = {
  ready: 'Pronto',
  playing: 'Em jogo',
  paused: 'Pausado',
  won: 'Vitória',
  gameover: 'Fim de jogo'
};

let accumulator = 0;
let lastTime = performance.now();

function resizeCanvas() {
  const rect = canvas.getBoundingClientRect();
  const dpr = Math.min(window.devicePixelRatio || 1, 3);
  const width = Math.max(1, Math.round(rect.width * dpr));
  const height = Math.max(1, Math.round(rect.height * dpr));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
  render(ctx, state);
}

function applyInput() {
  setLeftPressed(state, keys.has('ArrowLeft') || keys.has('KeyA') || touch.left);
  setRightPressed(state, keys.has('ArrowRight') || keys.has('KeyD') || touch.right);
}

function releaseAllInput() {
  keys.clear();
  touch.left = false;
  touch.right = false;
  activePointers.left.clear();
  activePointers.right.clear();
  clearInput(state);
}

function updateOverlay() {
  const visible = state.status !== 'playing';
  overlay.hidden = !visible;
  if (!visible) return;

  let content;
  if (state.status === 'ready') {
    content = {
      kicker: 'Pronto para jogar?',
      title: 'Breakout',
      text: 'Mova a raquete com ←/→ ou A/D. Use Espaço para lançar a bola e pausar.',
      action: 'Começar jogo'
    };
  } else if (state.status === 'paused') {
    content = {
      kicker: 'Pausa',
      title: 'Jogo pausado',
      text: 'Respire fundo. A partida continua exatamente de onde parou.',
      action: 'Retomar jogo'
    };
  } else if (state.status === 'won') {
    content = {
      kicker: 'Parabéns!',
      title: 'Você venceu!',
      text: `Todos os tijolos foram destruídos. Pontuação final: ${state.score}.`,
      action: 'Jogar novamente'
    };
  } else {
    content = {
      kicker: 'Fim de partida',
      title: 'Fim de jogo',
      text: `Você ficou sem vidas. Pontuação final: ${state.score}.`,
      action: 'Jogar novamente'
    };
  }

  overlayKicker.textContent = content.kicker;
  overlayTitle.textContent = content.title;
  overlayText.textContent = content.text;
  overlayAction.textContent = content.action;
}

function syncUI() {
  scoreEl.textContent = String(state.score);
  livesEl.textContent = String(state.lives);
  statusEl.textContent = statusLabels[state.status];
  pauseBtn.disabled = state.status !== 'playing';
  resumeBtn.disabled = state.status !== 'paused';

  if (state.status === 'ready') {
    hintEl.textContent = 'Use ←/→ ou A/D para mover. Espaço inicia a partida.';
  } else if (state.status === 'paused') {
    hintEl.textContent = 'O jogo está pausado.';
  } else if (state.status === 'won' || state.status === 'gameover') {
    hintEl.textContent = 'Use “Jogar novamente” para recomeçar.';
  } else if (state.ball.stuck) {
    hintEl.textContent = 'Pressione Espaço para lançar a bola.';
  } else {
    hintEl.textContent = 'Espaço pausa o jogo.';
  }

  updateOverlay();
  if (overlay.hidden) {
    if (document.activeElement === overlayAction) canvas.focus({ preventScroll: true });
  } else {
    overlayAction.focus({ preventScroll: true });
  }
}

function performAction() {
  if (state.status === 'ready') {
    startGame();
  } else if (state.status === 'playing') {
    if (!launchBall(state)) pauseGame(state);
  } else if (state.status === 'paused') {
    resumeGame(state);
  } else {
    releaseAllInput();
    restartGame(state);
  }
  syncUI();
}

function startGame() {
  if (state.status === 'ready') {
    state.status = 'playing';
    syncUI();
  }
}

function bindHoldButton(button, side) {
  const active = activePointers[side];
  button.addEventListener('pointerdown', (event) => {
    event.preventDefault();
    active.add(event.pointerId);
    button.setPointerCapture(event.pointerId);
    touch[side] = true;
    applyInput();
  });
  const release = (event) => {
    active.delete(event.pointerId);
    touch[side] = active.size > 0;
    applyInput();
  };
  button.addEventListener('pointerup', release);
  button.addEventListener('pointercancel', release);
  button.addEventListener('lostpointercapture', release);
  button.addEventListener('contextmenu', (event) => event.preventDefault());
}

function handleBlur() {
  releaseAllInput();
  if (pauseGame(state)) syncUI();
  accumulator = 0;
  lastTime = performance.now();
}

function frame(time) {
  const delta = Math.min(Math.max((time - lastTime) / 1000, 0), MAX_FRAME_TIME);
  lastTime = time;

  if (state.status === 'playing') {
    accumulator += delta;
    let needsUIUpdate = false;
    while (accumulator >= FIXED_STEP) {
      const events = step(state, FIXED_STEP);
      accumulator -= FIXED_STEP;
      if (events.some((event) => event !== 'wall' && event !== 'paddle')) {
        needsUIUpdate = true;
      }
      if (state.status !== 'playing' || state.ball.stuck) {
        accumulator = 0;
        break;
      }
    }
    if (needsUIUpdate) syncUI();
  } else {
    accumulator = 0;
  }

  render(ctx, state);
  requestAnimationFrame(frame);
}

const controlKeys = new Set(['ArrowLeft', 'ArrowRight', 'KeyA', 'KeyD', 'Space']);

window.addEventListener('keydown', (event) => {
  if (!controlKeys.has(event.code)) return;
  event.preventDefault();
  if (event.code === 'Space') {
    if (!event.repeat) performAction();
    return;
  }
  keys.add(event.code);
  applyInput();
});

window.addEventListener('keyup', (event) => {
  if (!controlKeys.has(event.code)) return;
  event.preventDefault();
  keys.delete(event.code);
  applyInput();
});

window.addEventListener('blur', handleBlur);
window.addEventListener('resize', resizeCanvas);
window.addEventListener('orientationchange', resizeCanvas);
document.addEventListener('visibilitychange', () => {
  if (document.hidden) handleBlur();
});

if ('ResizeObserver' in window) {
  new ResizeObserver(resizeCanvas).observe(document.querySelector('#stage'));
}

overlayAction.addEventListener('click', performAction);
pauseBtn.addEventListener('click', () => {
  if (pauseGame(state)) syncUI();
});
resumeBtn.addEventListener('click', () => {
  if (resumeGame(state)) syncUI();
});
restartBtn.addEventListener('click', () => {
  releaseAllInput();
  restartGame(state);
  syncUI();
});

bindHoldButton(document.querySelector('#touch-left'), 'left');
bindHoldButton(document.querySelector('#touch-right'), 'right');

resizeCanvas();
syncUI();
requestAnimationFrame(frame);

